const $=id=>document.getElementById(id);let model,home,step=0,complete=false;
const steps=[
 {key:'Neighborhood',title:'Which Ames neighborhood is the home in?',hint:'Choose a neighborhood code below. This model covers Ames, Iowa only.',type:'category'},
 {key:'GrLivArea',title:'How large is the above-ground living area?',hint:'Enter square feet, for example 1500. Basement space is separate.',min:334,max:4400},
 {key:'OverallQual',title:'How would you rate its overall quality?',hint:'Choose 1–10: 5 is average, 7 is good, 10 is excellent.',min:1,max:10},
 {key:'YearBuilt',title:'What year was the home built?',hint:'Enter a year from 1872–2010. This is a historical-data demo.',min:1872,max:2010},
 {key:'BedroomAbvGr',title:'How many bedrooms are above ground?',hint:'Enter a whole number from 0–8.',min:0,max:8},
 {key:'FullBath',title:'How many full bathrooms are above ground?',hint:'Enter 0–4. Half bathrooms and basement bathrooms can be edited below.',min:0,max:4},
 {key:'GarageCars',title:'How many cars fit in the garage?',hint:'Enter 0 for no garage, or 1–4 spaces.',min:0,max:4},
 {key:'TotalBsmtSF',title:'How large is the basement?',hint:'Enter square feet, or 0 for no basement.',min:0,max:5095}
];
function bubble(text,user=false){const b=document.createElement('div');b.className='bubble'+(user?' user':'');if(!user){const tag=document.createElement('small');tag.textContent='HOMEWISE';b.append(tag)}b.append(document.createTextNode(text));$('messages').append(b);$('messages').scrollTop=$('messages').scrollHeight}
function snapshot(){const labels={Neighborhood:'Neighborhood',GrLivArea:'Living area',BedroomAbvGr:'Bedrooms',FullBath:'Full bathrooms',YearBuilt:'Built',OverallQual:'Quality'};$('summary').replaceChildren();Object.entries(labels).forEach(([key,label])=>{const row=document.createElement('div');row.className='summary-row';const a=document.createElement('span'),b=document.createElement('strong');a.textContent=label;b.textContent=home[key]+(key==='GrLivArea'?' sq ft':key==='OverallQual'?' / 10':'');row.append(a,b);$('summary').append(row)})}
function ask(){const q=steps[step];$('status').textContent=`Question ${step+1} of ${steps.length}`;$('progress').style.width=step/steps.length*100+'%';bubble(q.title+'\n'+q.hint);$('answer').value='';$('answer').disabled=false;$('send').disabled=false;$('answer-label').textContent=q.key==='Neighborhood'?'Neighborhood code':'Your answer';$('answer').type=q.type==='category'?'text':'number';$('answer').placeholder=q.type==='category'?'e.g. NAmes':'Enter a number…';if(q.min!==undefined){$('answer').min=q.min;$('answer').max=q.max;$('answer').step='1'}else{$('answer').removeAttribute('min');$('answer').removeAttribute('max')}$('choices').replaceChildren();if(q.type==='category')model.schema.find(s=>s.name===q.key).options.forEach(v=>{const b=document.createElement('button');b.type='button';b.textContent=v;b.onclick=()=>accept(v);$('choices').append(b)});else if(q.key==='OverallQual')[5,6,7,8].forEach(v=>{const b=document.createElement('button');b.textContent=v;b.type='button';b.onclick=()=>accept(String(v));$('choices').append(b)})}
function consistent(key,v){home[key]=v;
 if(key==='GrLivArea'){const ratio=home['2ndFlrSF']/(home['1stFlrSF']+home['2ndFlrSF']);home['2ndFlrSF']=Math.round(v*ratio);home['1stFlrSF']=v-home['2ndFlrSF'];home.LowQualFinSF=0;}
 if(key==='YearBuilt'){home.YearRemodAdd=Math.max(1950,v);home.YrSold='2010';home.GarageYrBlt=v;}
 if(key==='GarageCars'){home.GarageArea=v*240;home.GarageType=v?'Attchd':'None';home.GarageFinish=v?'Unf':'None';home.GarageQual=home.GarageCond=v?'TA':'None';home.GarageYrBlt=v?home.YearBuilt:0;}
 if(key==='TotalBsmtSF'){home.BsmtFinSF1=home.BsmtFinSF2=0;home.BsmtUnfSF=v;home.BsmtFullBath=home.BsmtHalfBath=0;home.BsmtQual=home.BsmtCond=v?'TA':'None';home.BsmtExposure=v?'No':'None';home.BsmtFinType1=home.BsmtFinType2=v?'Unf':'None';}
}
function accept(raw){if(complete||!model)return;const q=steps[step];let value=raw.trim();if(q.type==='category'){const opts=model.schema.find(s=>s.name===q.key).options;value=opts.find(v=>v.toLowerCase()===value.toLowerCase());if(!value){$('error').textContent='Please choose one of the neighborhood codes above.';return}}else{if(!value||!Number.isInteger(Number(value))||Number(value)<q.min||Number(value)>q.max){$('error').textContent=`Enter a whole number between ${q.min} and ${q.max}.`;return}value=Number(value)}$('error').textContent='';consistent(q.key,value);bubble(String(value),true);step++;snapshot();renderFields();if(step<steps.length)ask();else finish()}
function showPrice(){const price=predictHouse(home,model);$('price').textContent=new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(price);$('price-note').textContent='Estimated historical sale price · USD';snapshot();return $('price').textContent}
function finish(){complete=true;$('progress').style.width='100%';$('status').textContent='Estimate ready';$('choices').replaceChildren();$('answer').value='';$('answer').disabled=true;$('send').disabled=true;$('answer').placeholder='Edit details below or start over';try{const price=showPrice();bubble(`Your estimated sale price is ${price} (USD).\n\nThis uses your answers plus the example home's remaining details. In guided mode, garage area uses 240 sq ft per car and the basement is set to unfinished. The editable details below show the exact inputs used. This is a historical estimate, not today's market value.`)}catch(e){bubble('Please review the property details below: '+e.message);$('price').textContent='Review details';$('price-note').textContent='The current details need correction.'}}
function reset(){home={...model.defaults};step=0;complete=false;$('messages').replaceChildren();$('price').textContent="Let's find out.";$('price-note').textContent='Your estimate will appear here after a few details.';$('error').textContent='';$('detail-error').textContent='';bubble("Hi! I'm your house-price assistant. I'll ask 8 quick questions.\n\nWe start with an example home's other features; you can review and change every input below.");snapshot();renderFields();ask()}
function renderFields(){$('fields').replaceChildren();model.schema.forEach(s=>{const wrap=document.createElement('div');wrap.className='field';const label=document.createElement('label');label.htmlFor='f-'+s.name;label.textContent=s.name;let input;if(s.type==='category'){input=document.createElement('select');s.options.forEach(v=>{const o=document.createElement('option');o.value=v;o.textContent=v;input.append(o)})}else{input=document.createElement('input');input.type='number';input.min=s.min;input.max=s.max;input.step='any';input.required=true}input.id='f-'+s.name;input.name=s.name;input.value=home[s.name];wrap.append(label,input);$('fields').append(wrap)})}
$('chat-form').onsubmit=e=>{e.preventDefault();accept($('answer').value)};
$('restart').onclick=()=>reset();$('example').onclick=()=>{home={...model.examples[0]};step=steps.length;complete=true;$('messages').replaceChildren();bubble('I loaded a complete example from your test.csv. All property fields are available below.');renderFields();finish()};
$('details-form').onsubmit=e=>{e.preventDefault();const updated={};new FormData(e.target).forEach((v,k)=>updated[k]=model.schema.find(s=>s.name===k).type==='number'?Number(v):v);try{predictHouse(updated,model);home=updated;$('detail-error').textContent='';step=steps.length;complete=true;finish()}catch(err){$('detail-error').textContent=err.message}};
$('about').onclick=()=>$('method').scrollIntoView({behavior:'smooth'});
fetch('model.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(m=>{model=m;const a=m.metrics;$('metrics').textContent=`${a.features} model features · ${a.test} validation homes`;$('method-metrics').textContent=`Validation: log-price RMSE ${a.logRMSE.toFixed(3)} and mean absolute error $${Math.round(a.dollarMAE).toLocaleString()} on ${a.test} homes. As in the notebook, preprocessing used the combined train/test feature data, so these are exploratory validation results. Preprocessing includes compatibility adjustments for modern SciPy. Default-filled inputs add uncertainty.`;$('restart').disabled=$('example').disabled=false;reset()}).catch(()=>{$('status').textContent='Model unavailable';bubble('The model could not load. Please refresh the page. If running locally, use the supplied Python server command instead of double-clicking index.html.')});
